import axios from '../../api/axiosInstance';

// Products — backend ProductController (`/products`, generated by make:module). REST; 422 = field errors.
// Product = { id, sku, barcode, name, description, category_id, category: {id,name}|null, unit,
//             price (centavos), cost (centavos)|null, tax_class: vatable|exempt|zero_rated, sc_pwd_eligible,
//             track_stock, reorder_level, on_hand (sum over locations; null when not tracked), active, created_at, updated_at }
// - getAll({ page, per_page, search (name, sku, exact barcode), category_id, active, sort: sku|name|price|active|created_at, order })
//     → { data: [Product], meta: { current_page, per_page, total } }   (product-list)
// - getById(id) → { data: Product }                    (product-list | product-edit)
// - create({ sku, barcode, name, description, category_id, unit, price, cost, tax_class, sc_pwd_eligible,
//            track_stock, reorder_level, active }) → 201 { data }   (product-create; sku upper-cased; sku/barcode unique)
// - update(id, same) → { data }                          (product-edit)
// - remove(id) → { message }                             (product-delete; 422 if it has stock history → deactivate)
const productApi = {
  getAll:  (params)      => axios.get('/products', { params }),
  getById: (id)          => axios.get(`/products/${id}`),
  create:  (payload)     => axios.post('/products', payload),
  update:  (id, payload) => axios.put(`/products/${id}`, payload),
  remove:  (id)          => axios.delete(`/products/${id}`),
};

export default productApi;
